package graph

import("context";"encoding/json";"time")
func(s *Service) CreateGraph(ctx context.Context,c CommandContext,p CreateGraphInput)(Result,error){now:=time.Now().UTC();g:=Graph{ID:c.GraphID,Namespace:c.Namespace,ExternalRef:p.ExternalRef,Description:p.Description,State:"active",Metadata:p.Metadata,CreatedAt:now,UpdatedAt:now};if g.Metadata==nil{g.Metadata=map[string]any{}};return s.mutate(ctx,c,"CreateGraph",p,&g,func(st *State)(map[string]any,error){n,e:=newNode(st,"origin","recorded",p.Title,OriginPayload{Request:p.Request},c.ActorID);if e!=nil{return nil,e};return map[string]any{"graph_id":c.GraphID,"origin_id":n.ID,"node_revision":1},nil})}
func(s *Service) AddGoal(ctx context.Context,c CommandContext,p AddGoalInput)(Result,error){return s.mutate(ctx,c,"AddGoal",p,nil,func(st *State)(map[string]any,error){o:=ref(origin(st));n,e:=newNode(st,"goal","open",p.Title,p.GoalPayload,c.ActorID);if e!=nil{return nil,e};id:=n.ID;ed,e:=addEdge(st,o,ref(n),"spawns",c.ActorID);return map[string]any{"goal_id":id,"node_revision":1,"spawns_edge_id":ed},e})}
func(s *Service) ProposeWork(ctx context.Context,c CommandContext,p ProposeWorkInput)(Result,error){return s.mutate(ctx,c,"ProposeWork",p,nil,func(st *State)(map[string]any,error){if len(p.Parents)>s.Limits.MaxReferences||p.ExecutionID!=""{return nil,Err("invalid_argument","Invalid work parents or execution identity.")};parents:=p.Parents;if len(parents)==0{parents=[]Ref{ref(origin(st))}};for _,r:=range parents{n,e:=current(st,r);if e!=nil{return nil,e};if n.Kind!="origin"{if _,e=closure(st,r,map[string]bool{});e!=nil{return nil,e}}};n,e:=newNode(st,"work_item","open",p.Title,p.WorkPayload,c.ActorID);if e!=nil{return nil,e};nr:=ref(n);ids:=[]string{};for _,r:=range parents{id,e:=addEdge(st,r,nr,"derived_from",c.ActorID);if e!=nil{return nil,e};ids=append(ids,id)};return map[string]any{"work_item_id":nr.NodeID,"node_revision":1,"lineage_edge_ids":ids},nil})}
func(s *Service) TransitionWork(ctx context.Context,c CommandContext,p TransitionWorkInput)(Result,error){return s.mutate(ctx,c,"TransitionWork",p,nil,func(st *State)(map[string]any,error){n,e:=current(st,p.Node);if e!=nil{return nil,e};if n.Kind!="work_item"{return nil,Err("invalid_relation","Expected work item.")};if c.Execution!=nil&&c.Execution.WorkItemID!=n.ID{return nil,Err("stale_execution","Completion does not match assignment.")};old:=*n.Current();allowed:=map[string]map[string]bool{"open":{"running":true,"stopped":true},"running":{"paused":true,"done":true,"blocked":true,"exhausted":true,"stopped":true},"paused":{"open":true,"stopped":true},"blocked":{"open":true},"exhausted":{"open":true},"stopped":{"open":true}};if !allowed[old.State][p.State]{return nil,Err("invalid_transition","Work transition is not allowed.")};var w WorkPayload;_ = json.Unmarshal(old.Payload,&w);if p.State=="running"{if !ValidID(p.ExecutionID){return nil,Err("invalid_argument","A new execution identity is required.")};for _,other:=range st.Nodes{if other.Kind!="work_item"{continue};for _,r:=range other.Revisions{if r.State=="running"{var prev WorkPayload;_ = json.Unmarshal(r.Payload,&prev);if prev.ExecutionID==p.ExecutionID{return nil,Err("stale_execution","Execution identity has already been used.")}}}};for _,ed:=range st.Edges{if ed.Relation=="depends_on"&&ed.SourceID==n.ID{pr,_:=findNode(st,ed.TargetID);if pr.Current().State!="done"{return nil,Err("invalid_transition","Prerequisite work is not done.")}}};w.ExecutionID=p.ExecutionID}else if p.ExecutionID!=""{return nil,Err("invalid_argument","Execution identity is only assigned when entering running.")};w.Reason=p.Reason;revise(n,p.State,old.Title,raw(w),c.ActorID);return nodeData(n),nil})}
func(s *Service) RecordObservation(ctx context.Context,c CommandContext,p RecordObservationInput)(Result,error){return s.mutate(ctx,c,"RecordObservation",p,nil,func(st *State)(map[string]any,error){if c.Execution==nil{return nil,Err("stale_execution","A bound running producer is required.")};producer,e:=checkExecution(st,c.Execution);if e!=nil{return nil,e};pr:=ref(producer);if len(p.Resources)>s.Limits.MaxReferences{return nil,Err("limit_exceeded","Too many resources.")};if !nonempty(p.Evidence)&&len(p.Resources)==0{return nil,Err("invalid_argument","Observation requires evidence or a resource.")};n,e:=newNode(st,"observation","active",p.Title,p.EvidencePayload,c.ActorID);if e!=nil{return nil,e};nr:=ref(n);ed,e:=addEdge(st,pr,nr,"yields",c.ActorID);if e!=nil{return nil,e};ids,e:=resources(st,nr,p.Resources,c.ActorID);return map[string]any{"observation_id":nr.NodeID,"node_revision":1,"yields_edge_id":ed,"resource_reference_ids":ids},e})}
func(s *Service) RecordConclusion(ctx context.Context,c CommandContext,p RecordConclusionInput)(Result,error){return s.mutate(ctx,c,"RecordConclusion",p,nil,func(st *State)(map[string]any,error){if len(p.Supports)==0{return nil,Err("invalid_argument","Conclusion requires support.")};if len(p.Supports)>s.Limits.MaxReferences||len(p.Resources)>s.Limits.MaxReferences{return nil,Err("limit_exceeded","Too many references.")};for _,r:=range p.Supports{if _,e:=closure(st,r,map[string]bool{});e!=nil{return nil,e}};var pr Ref;if c.Execution!=nil{pn,e:=checkExecution(st,c.Execution);if e!=nil{return nil,e};pr=ref(pn)};n,e:=newNode(st,"conclusion","active",p.Title,p.EvidencePayload,c.ActorID);if e!=nil{return nil,e};nr:=ref(n);ids:=[]string{};for _,r:=range p.Supports{id,e:=addEdge(st,r,nr,"supports",c.ActorID);if e!=nil{return nil,e};ids=append(ids,id)};rs,e:=resources(st,nr,p.Resources,c.ActorID);if e!=nil{return nil,e};out:=map[string]any{"conclusion_id":nr.NodeID,"node_revision":1,"support_edge_ids":ids,"resource_reference_ids":rs};if pr.NodeID!=""{id,e:=addEdge(st,pr,nr,"yields",c.ActorID);if e!=nil{return nil,e};out["yields_edge_id"]=id};return out,nil})}
func(s *Service) AddSupport(ctx context.Context,c CommandContext,p AddSupportInput)(Result,error){return s.mutate(ctx,c,"AddSupport",p,nil,func(st *State)(map[string]any,error){if _,e:=closure(st,p.Source,map[string]bool{});e!=nil{return nil,e};n,e:=current(st,p.Target);if e!=nil{return nil,e};if !(n.Kind=="conclusion"&&n.Current().State=="active")&&!(n.Kind=="goal"&&(n.Current().State=="open"||n.Current().State=="needs_review")){return nil,Err("invalid_relation","Support target must be an active conclusion or unaccepted goal.")};id,e:=addEdge(st,p.Source,p.Target,"supports",c.ActorID);return map[string]any{"edge_id":id},e})}
func(s *Service) AcceptGoal(ctx context.Context,c CommandContext,p AcceptGoalInput)(Result,error){return s.mutate(ctx,c,"AcceptGoal",p,nil,func(st *State)(map[string]any,error){g,e:=current(st,p.Goal);if e!=nil{return nil,e};if g.Kind!="goal"||(g.Current().State!="open"&&g.Current().State!="needs_review"){return nil,Err("invalid_transition","Goal cannot be accepted in this state.")};if len(p.SupportEdgeIDs)==0||len(p.SupportEdgeIDs)>s.Limits.MaxReferences||!nonempty(p.Rationale)||(p.Method!="human"&&p.Method!="validator"&&p.Method!="agent"){return nil,Err("invalid_argument","Explicit support, method and rationale are required.")};if len(unique(p.SupportEdgeIDs))!=len(p.SupportEdgeIDs){return nil,Err("invalid_argument","Duplicate direct support.")};ids:=[]string{};for _,id:=range p.SupportEdgeIDs{ed:=edgeByID(st,id);if ed==nil||ed.Relation!="supports"||ed.TargetID!=g.ID||ed.TargetRevision!=g.CurrentRevision{return nil,Err("stale_evidence","Selected support does not target the current goal revision.")};sub,e:=closure(st,Ref{ed.SourceID,ed.SourceRevision},map[string]bool{});if e!=nil{return nil,e};ids=append(ids,id);ids=append(ids,sub...)};ids=unique(ids);evidence:=map[string]Ref{};for _,id:=range ids{ed:=edgeByID(st,id);evidence[ed.SourceID]=Ref{ed.SourceID,ed.SourceRevision}};rs:=[]string{};for _,r:=range st.ResourceRefs{if er,ok:=evidence[r.NodeID];ok&&er.Revision==r.NodeRevision{rs=append(rs,r.ID)}};rs=unique(rs);reviewed:=[]Ref{};keys:=[]string{};for id:=range evidence{keys=append(keys,id)};for _,id:=range unique(keys){reviewed=append(reviewed,evidence[id])};old:=*g.Current();revise(g,"met",old.Title,old.Payload,c.ActorID);a:=Acceptance{ID:NewID(),GoalID:g.ID,EvaluatedRevision:p.Goal.Revision,ResultingRevision:g.CurrentRevision,SupportEdgeIDs:ids,ReviewedResourceIDs:rs,ActorID:c.ActorID,Method:p.Method,Rationale:p.Rationale,State:"current",CreatedAt:time.Now().UTC()};st.Acceptances=append(st.Acceptances,a);return map[string]any{"acceptance_id":a.ID,"resulting_goal_revision":a.ResultingRevision,"reviewed_evidence":reviewed,"support_edge_ids":ids,"reviewed_resource_ids":rs},nil})}
func(s *Service) ReviseNode(ctx context.Context,c CommandContext,p ReviseNodeInput)(Result,error){return s.mutate(ctx,c,"ReviseNode",p,nil,func(st *State)(map[string]any,error){n,e:=current(st,p.Node);if e!=nil{return nil,e};r:=*n.Current();valid:=(n.Kind=="goal"&&(r.State=="open"||r.State=="needs_review"||r.State=="met"))||(n.Kind=="work_item"&&r.State=="open")||((n.Kind=="observation"||n.Kind=="conclusion"||n.Kind=="hint")&&r.State=="active");if !valid{return nil,Err("invalid_transition","Node cannot be revised in this state.")};if !nonempty(p.Title){return nil,Err("invalid_argument","Title is required.")};if e=validatePayload(n.Kind,p.Payload);e!=nil{return nil,e};if n.Kind=="work_item"{var old,updated WorkPayload;_ = json.Unmarshal(r.Payload,&old);_ = json.Unmarshal(p.Payload,&updated);if old.ExecutionID!=updated.ExecutionID{return nil,Err("invalid_argument","Revision cannot change execution identity.")}};if n.Kind=="observation"{var ep EvidencePayload;_ = json.Unmarshal(p.Payload,&ep);if !nonempty(ep.Evidence){return nil,Err("invalid_argument","Revised observation requires inline evidence; resources do not carry forward.")}};invalidate(st,n.ID,c.ActorID,"Node revision changed.");if r.State=="met"{r.State="needs_review"};revise(n,r.State,p.Title,p.Payload,c.ActorID);return nodeData(n),nil})}
func(s *Service) AddDependency(ctx context.Context,c CommandContext,p DependencyInput)(Result,error){return s.dependency(ctx,c,p,false)}
func(s *Service) RemoveDependency(ctx context.Context,c CommandContext,p DependencyInput)(Result,error){return s.dependency(ctx,c,p,true)}
func(s *Service) dependency(ctx context.Context,c CommandContext,p DependencyInput,remove bool)(Result,error){kind:="AddDependency";if remove{kind="RemoveDependency"};return s.mutate(ctx,c,kind,p,nil,func(st *State)(map[string]any,error){n,e:=current(st,p.Dependent);if e!=nil{return nil,e};if n.Kind!="work_item"||n.Current().State!="open"{return nil,Err("invalid_transition","Dependency edits require open work.")};if remove{for i,ed:=range st.Edges{if ed.SourceID==n.ID&&ed.TargetID==p.PrerequisiteID&&ed.Relation=="depends_on"{st.Edges=append(st.Edges[:i],st.Edges[i+1:]...);return map[string]any{"edge_id":ed.ID},nil}};return nil,Err("not_found","Dependency not found.")};id,e:=addEdge(st,p.Dependent,Ref{p.PrerequisiteID,0},"depends_on",c.ActorID);return map[string]any{"edge_id":id},e})}
func(s *Service) AddHint(ctx context.Context,c CommandContext,p AddHintInput)(Result,error){return s.mutate(ctx,c,"AddHint",p,nil,func(st *State)(map[string]any,error){n,e:=newNode(st,"hint","active",p.Title,p.HintPayload,c.ActorID);if e!=nil{return nil,e};return map[string]any{"hint_id":n.ID,"node_revision":1},nil})}
func(s *Service) ConsumeHint(ctx context.Context,c CommandContext,p NodeActionInput)(Result,error){return s.nodeAction(ctx,c,p,"ConsumeHint")}
func(s *Service) AbandonGoal(ctx context.Context,c CommandContext,p NodeActionInput)(Result,error){return s.nodeAction(ctx,c,p,"AbandonGoal")}
func(s *Service) ReopenGoal(ctx context.Context,c CommandContext,p NodeActionInput)(Result,error){return s.nodeAction(ctx,c,p,"ReopenGoal")}
func(s *Service) RetractEvidence(ctx context.Context,c CommandContext,p NodeActionInput)(Result,error){return s.nodeAction(ctx,c,p,"RetractEvidence")}
func(s *Service) nodeAction(ctx context.Context,c CommandContext,p NodeActionInput,kind string)(Result,error){return s.mutate(ctx,c,kind,p,nil,func(st *State)(map[string]any,error){n,e:=current(st,p.Node);if e!=nil{return nil,e};r:=*n.Current();to:="";switch kind{case "ConsumeHint":if n.Kind=="hint"&&r.State=="active"{to="consumed"};case "RetractEvidence":if (n.Kind=="observation"||n.Kind=="conclusion")&&r.State=="active"{to="retracted"};case "AbandonGoal":if n.Kind=="goal"&&(r.State=="open"||r.State=="met"||r.State=="needs_review"){to="abandoned"};case "ReopenGoal":if n.Kind=="goal"&&(r.State=="met"||r.State=="abandoned"||r.State=="needs_review"){to="open"}};if to==""{return nil,Err("invalid_transition","Node transition is not allowed.")};invalidate(st,n.ID,c.ActorID,kind+": "+p.Reason);revise(n,to,r.Title,r.Payload,c.ActorID);return nodeData(n),nil})}
func(s *Service) AttachResource(ctx context.Context,c CommandContext,p AttachResourceInput)(Result,error){return s.mutate(ctx,c,"AttachResource",p,nil,func(st *State)(map[string]any,error){n,e:=findNode(st,p.Node.NodeID);if e!=nil{return nil,e};if p.Node.Revision<1||p.Node.Revision>n.CurrentRevision{return nil,Err("not_found","Node revision not found.")};ids,e:=resources(st,p.Node,[]ResourceInput{p.Resource},c.ActorID);if e!=nil{return nil,e};return map[string]any{"resource_reference_id":ids[0]},nil})}
func(s *Service) SetGraphState(ctx context.Context,c CommandContext,p SetGraphStateInput)(Result,error){return s.mutate(ctx,c,"SetGraphState",p,nil,func(st *State)(map[string]any,error){from:=st.Graph.State;if !(from=="active"&&p.State=="closed")&&!(from=="closed"&&(p.State=="active"||p.State=="archived")){return nil,Err("invalid_transition","Graph transition is not allowed.")};if p.State=="closed"{for _,n:=range st.Nodes{if n.Kind=="work_item"&&n.Current().State=="running"{return nil,Err("invalid_transition","Running work prevents closing.")}}};st.Graph.State=p.State;return map[string]any{"state":p.State},nil})}
